function getVoiceParams(languageCode = "en-US", voiceOption = "neutral") {
  const lang = typeof languageCode === "string" ? languageCode : "en-US";
  const normalized = voiceOption ? String(voiceOption).toLowerCase() : "neutral";
  const exact = VOICE_MAP[lang];
  const base = lang.split("-")[0] ? `${lang.split("-")[0]}` : null;
  const baseMap = base ? VOICE_MAP[base] : null;
  const fallback = VOICE_MAP["en-US"];
  const map = exact || baseMap || fallback;
  const voiceEntry = map[normalized] || map["neutral"] || fallback["neutral"];
  return {
    voiceName: voiceEntry.name,
    ssmlGender: voiceEntry.ssmlGender
  };
}

// public/tts/ttsClient.js
function createTTSClient({
  TTS_API_URL: TTS_API_URL2 = TTS_API_URL,
  postStatus,
  controlsManager,
  getWidgetWindow
}) {
  let audioEl = null;
  let lastVoiceOption = "neutral";
  const stopAndClearAudio = () => {
    if (audioEl) {
      audioEl.pause();
      audioEl.onplay = audioEl.onpause = audioEl.onended = audioEl.onerror = null;
      audioEl = null;
    }
    if (controlsManager) controlsManager.remove();
  };
  const performFetchAndPlay = async ({
    text,
    language = "en-US",
    voiceName,
    speakingRate = 1,
    audioEncoding = "MP3",
    selectionRect = null
  }) => {
    if (!text || !text.trim()) {
      if (postStatus)
        postStatus("error", { message: "No text supplied to TTS." });
      return;
    }
    stopAndClearAudio();
    if (postStatus) postStatus("loading");
    try {
      const { voiceName: mappedVoiceName, ssmlGender } = getVoiceParams(
        language,
        voiceName || "neutral"
      );
      lastVoiceOption = voiceName || "neutral";
      const payload = {
        text,
        languageCode: language,
        voiceName: mappedVoiceName,
        ssmlGender,
        audioConfig: { audioEncoding, speakingRate }
      };
      const res = await fetch(TTS_API_URL2, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!res.ok) {
        const body = await res.text();
        throw new Error(`TTS backend error: ${res.status} ${body}`);
      }
      const data = await res.json();
      if (!data?.audioContent)
        throw new Error("No audioContent in TTS response");
      audioEl = new Audio(`data:audio/mp3;base64,${data.audioContent}`);
      audioEl.onplay = () => {
        if (postStatus) postStatus("playing");
        if (controlsManager) controlsManager.showAt(selectionRect);
        if (controlsManager && typeof controlsManager.setHandlers === "function") {
          controlsManager.setHandlers({
            onPlay: () => {
              if (audioEl && audioEl.paused)
                audioEl.play().catch((err) => {
                  console.error("Resume play error", err);
                  if (postStatus)
                    postStatus("error", { message: "Resume failed" });
                });
            },
            onPause: () => {
              if (audioEl && !audioEl.paused) audioEl.pause();
            },
            onStop: () => {
              stopAndClearAudio();
              if (postStatus) postStatus("stopped");
            },
            onClose: () => {
              if (controlsManager) controlsManager.remove();
            }
          });
        }
        if (controlsManager && typeof controlsManager.setIconResolver === "function" && getWidgetWindow) {
          controlsManager.setIconResolver((path) => {
            try {
              const widget = getWidgetWindow && getWidgetWindow();
              if (widget && widget.origin && path && path.startsWith("/")) {
                return `${widget.origin}${path}`;
              }
            } catch (e) {
              console.warn("Failed to resolve icon URL:", e);
            }
            return path;
          });
        }
        if (controlsManager && controlsManager.setPlaying)
          controlsManager.setPlaying();
      };
      audioEl.onpause = () => {
        if (postStatus) postStatus("paused");
        if (controlsManager && controlsManager.setPaused)
          controlsManager.setPaused();
      };
      audioEl.onended = () => {
        if (postStatus) postStatus("ended");
        stopAndClearAudio();
      };
      audioEl.onerror = (e) => {
        console.error("Audio playback error", e);
        if (postStatus)
          postStatus("error", { message: "Audio playback error" });
        stopAndClearAudio();
      };
      await audioEl.play();
    } catch (err) {
      console.error("TTS fetch/play error", err);
      if (err.message.includes("limit of 5000 bytes")) {
        postStatus("error", {
          message: "Text too long for TTS. Please select less text."
        });
      } else {
        postStatus("error", { message: "TTS error: " + err.message });
      }
      stopAndClearAudio();
    }
  };
  const pause = () => {
    if (audioEl && !audioEl.paused) audioEl.pause();
  };
  const resume = () => {
    if (audioEl && audioEl.paused) {
      audioEl.play().catch((err) => {
        console.error("Resume error", err);
        if (postStatus) postStatus("error", { message: "Resume failed" });
      });
    }
  };
  const stop = () => {
    stopAndClearAudio();
  };
  const getLastVoice = () => lastVoiceOption;
  return {
    performFetchAndPlay,
    pause,
    resume,
    stop,
    getLastVoice
  };
}

// public/tts/ttsFeature.js
function setupTTSFeature() {
  if (window.__boafo_tts_feature_initialized) return;
  window.__boafo_tts_feature_initialized = true;
  const getWidgetWindow = () => {
    const container = document.getElementById("accessibility-widget-container");
    if (!container) return null;
    const iframe = container.querySelector("iframe");
    if (!iframe) return null;
    try {
      const href = iframe.getAttribute("src") || iframe.src || "";
      const origin = href ? new URL(href, window.location.href).origin : null;
      const win = iframe.contentWindow || null;
      return { win, origin };
    } catch (err) {
      console.warn("Failed to get widget window:", err);
      return null;
    }
  };
  let currentSourceWindow = null;
  let currentSourceOrigin = null;
  function postStatus(status, extra = {}) {
    if (currentSourceWindow && currentSourceOrigin) {
      try {
        currentSourceWindow.postMessage(
          { type: "TTS_STATUS", payload: { status, ...extra } },
          currentSourceOrigin
        );
      } catch (e) {
        console.warn("Failed to post status to current source window:", e);
      }
    }
    const widget = getWidgetWindow();
    if (widget && widget.win && widget.origin && allowedIframeOrigins.includes(widget.origin)) {
      try {
        widget.win.postMessage(
          { type: "TTS_STATUS", payload: { status, ...extra } },
          widget.origin
        );
      } catch (e) {
        console.warn("Failed to post status to widget window:", e);
      }
    }
  }
  const controlsManager = createControlsManager({
    ICONS,
    autoHideMs: CONTROLS_AUTO_HIDE_MS,
    postStatus
  });
  const ttsClient = createTTSClient({
    TTS_API_URL,
    postStatus,
    controlsManager,
    getWidgetWindow
  });
  const handleMessage = (event) => {
    if (!(allowedIframeOrigins.includes(event.origin) || event.origin === window.location.origin))
      return;
    currentSourceOrigin = event.origin;
    currentSourceWindow = event.source;
    const { type, payload } = event.data || {};
    switch (type) {
      case "TTS_READ":
        (async () => {
          try {
            let text = payload?.text || "";
            let selectionRect = null;
            if (!text) {
              if (payload?.mode === "selection") {
                text = window.getSelection && window.getSelection().toString() || "";
                try {
                  const sel = window.getSelection();
                  if (sel && sel.rangeCount) {
                    const r = sel.getRangeAt(0);
                    const rect = r.getBoundingClientRect();
                    if (rect && rect.width + rect.height > 0)
                      selectionRect = rect;
                  }
                } catch (e) {
                  selectionRect = null;
                  console.warn("Failed to get selection rect:", e);
                }
              } else if (payload?.mode === "auto") {
                text = document.body?.innerText || "";
                if (text.length > MAX_TEXT_LENGTH)
                  text = text.substring(0, MAX_TEXT_LENGTH);
              }
            }
            await ttsClient.performFetchAndPlay({
              text,
              language: payload?.language || "en-US",
              voiceName: payload?.voiceName,
              speakingRate: payload?.speakingRate ?? 1,
              selectionRect
            });
          } catch (err) {
            console.error("TTS_READ handler error", err);
            postStatus("error", { message: err?.message || String(err) });
          }
        })();
        break;
      case "TTS_PAUSE":
        ttsClient.pause();
        break;
      case "TTS_RESUME":
        ttsClient.resume();
        break;
      case "TTS_STOP":
        ttsClient.stop();
        postStatus("stopped");
        break;
      default:
        break;
    }
  };
  const onKeyDown = (e) => {
    const target = e.target;
    const tag = target && target.tagName ? target.tagName.toUpperCase() : null;
    const isEditable = target && target.isContentEditable === true || tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT";
    if (isEditable) return;
    if (e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey && (e.key === "r" || e.key === "R")) {
      e.preventDefault();
      const selText = window.getSelection && window.getSelection().toString() || "";
      if (!selText.trim()) {
        const msg = "No text selected. Highlight the text you want read and press Alt R again.";
        const widget2 = getWidgetWindow();
        if (widget2 && widget2.win && widget2.origin && allowedIframeOrigins.includes(widget2.origin)) {
          currentSourceWindow = widget2.win;
          currentSourceOrigin = widget2.origin;
        }
        ttsClient.performFetchAndPlay({
          text: msg,
          language: "en-US",
          voiceName: ttsClient.getLastVoice ? ttsClient.getLastVoice() : "neutral",
          speakingRate: 1,
          selectionRect: null
        });
        return;
      }
      let selectionRect = null;
      try {
        const sel = window.getSelection();
        if (sel && sel.rangeCount) {
          const r = sel.getRangeAt(0);
          const rect = r.getBoundingClientRect();
          if (rect && rect.width + rect.height > 0) selectionRect = rect;
        }
      } catch (err) {
        selectionRect = null;
        console.warn("Failed to get selection rect:", err);
      }
      const widget = getWidgetWindow();
      if (widget && widget.win && widget.origin && allowedIframeOrigins.includes(widget.origin)) {
        currentSourceWindow = widget.win;
        currentSourceOrigin = widget.origin;
      }
      ttsClient.performFetchAndPlay({
        text: selText,
        language: "en-US",
        voiceName: ttsClient.getLastVoice ? ttsClient.getLastVoice() : "neutral",
        speakingRate: 1,
        selectionRect
      });
    }
  };
  window.addEventListener("message", handleMessage, false);
  window.addEventListener("keydown", onKeyDown, false);
  window.__boafo_tts = {
    read: (opts) => handleMessage({
      origin: window.location.origin,
      source: window,
      data: { type: "TTS_READ", payload: opts }
    }),
    pause: () => handleMessage({
      origin: window.location.origin,
      source: window,
      data: { type: "TTS_PAUSE" }
    }),
    resume: () => handleMessage({
      origin: window.location.origin,
      source: window,
      data: { type: "TTS_RESUME" }
    }),
    stop: () => handleMessage({
      origin: window.location.origin,
      source: window,
      data: { type: "TTS_STOP" }
    })
  };
}

