var SUMMARIZER_API_URL = "https://boafo-accessibility-services-production-b6b5.up.railway.app/features/summarize";
var allowedIframeOrigins2 = [
  "https://boafo-plugin-widget.vercel.app"
];

// public/summarizer/summarizerClient.js
function createSummarizerClient({
  SUMMARIZER_API_URL: SUMMARIZER_API_URL2 = SUMMARIZER_API_URL,
  postStatus
}) {
  const summarizeText = async ({ text, length = "medium" }) => {
    postStatus("loading");
    try {
      const payload = { tabContent: text, length };
      const response = await fetch(SUMMARIZER_API_URL2, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });
      if (!response.ok) {
        const errorBody = await response.text();
        throw new Error(
          `Summarizer backend error: ${response.status} - ${errorBody}`
        );
      }
      const result = await response.json();
      if (!result?.data) {
        throw new Error("No summary data received.");
      }
      return result.data;
    } catch (error) {
      console.error("Summarization fetch error", error);
      postStatus("error", { message: error?.message || "Unexpected error." });
      throw error;
    }
  };
  return { summarizeText };
}

// public/summarizer/summarizerFeature.js
function setupSummarizerFeature() {
  if (window.__boafo_summarizer_feature_initialized) return;
  window.__boafo_summarizer_feature_initialized = true;
  let currentSourceWindow = null;
  let currentSourceOrigin = null;
  function postStatus(status, extra = {}) {
    if (currentSourceWindow && currentSourceOrigin) {
      try {
        currentSourceWindow.postMessage(
          { type: "SUMMARIZER_STATUS", payload: { status, ...extra } },
          currentSourceOrigin
        );
      } catch (e) {
        console.warn("Failed to post status:", e);
      }
    }
  }
  const summarizerClient = createSummarizerClient({
    SUMMARIZER_API_URL,
    postStatus
  });
  async function runSummarize(mode = "auto", length = "medium") {
    try {
      showToast("\u23F3 Summarizing...", "info");
      let text = "";
      if (mode === "selection") {
        text = window.getSelection && window.getSelection().toString() || "";
      } else {
        text = document.body?.innerText || "";
      }
      if (!text.trim()) {
        showToast("\u26A0\uFE0F No text found to summarize.", "error");
        return;
      }
      const summary = await summarizerClient.summarizeText({
        text,
        length
      });
      showToast("\u2705 Summary ready", "success");
      showSummaryPopup(summary);
    } catch (err) {
      console.error("Summarizer error:", err);
      showToast("\u274C " + (err?.message || "Unexpected error."), "error");
    }
  }
  function onKeyDown(e) {
    const target = e.target;
    const tag = target && target.tagName ? target.tagName.toUpperCase() : null;
    const isEditable = target && target.isContentEditable === true || tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT";
    if (isEditable) return;
    if (e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey && (e.key === "s" || e.key === "S")) {
      e.preventDefault();
      let selText = window.getSelection && window.getSelection().toString() || "";
      const mode = selText.trim().length > 0 ? "selection" : "auto";
      runSummarize(mode, "medium");
    }
  }
  const handleMessage = (event) => {
    if (!allowedIframeOrigins2.includes(event.origin)) return;
    currentSourceOrigin = event.origin;
    currentSourceWindow = event.source;
    const { type, payload } = event.data || {};
    if (type === "SUMMARIZE_CONTENT") {
      (async () => {
        try {
          showToast("\u23F3 Summarizing...", "info");
          let text = "";
          if (payload?.mode === "selection") {
            text = window.getSelection && window.getSelection().toString() || "";
          } else if (payload?.mode === "auto") {
            text = document.body?.innerText || "";
          }
          if (!text.trim()) {
            postStatus("error", { message: "No text found to summarize." });
            showToast("\u26A0\uFE0F No text found to summarize.", "error");
            return;
          }
          const summary = await summarizerClient.summarizeText({
            text,
            length: payload?.length || "medium"
          });
          postStatus("success", { summary });
          showToast("\u2705 Summary ready", "success");
          showSummaryPopup(summary);
        } catch (err) {
          console.error("Summarizer error:", err);
          postStatus("error", { message: err?.message || "Unexpected error." });
          showToast("\u274C " + (err?.message || "Unexpected error."), "error");
        }
      })();
    }
  };
  window.addEventListener("keydown", onKeyDown, false);
  window.addEventListener("message", handleMessage, false);
}
